// Current piece state
struct Piece {
    piece_type: PieceType,
    rotation: usize,
    x: i32,
    y: i32,
}

impl Piece {
    fn new(piece_type: PieceType) -> Self {
        Piece {
            piece_type,
            rotation: 0,
            x: BOARD_WIDTH as i32 / 2 - 2,
            y: 0,
        }
    }

    fn rotate(&mut self) {
        self.rotation = (self.rotation + 1) % 4;
    }

    fn rotate_back(&mut self) {
        self.rotation = (self.rotation + 3) % 4;
    }
}

// Game board
struct Board {
    grid: [[Option<PieceType>; BOARD_HEIGHT]; BOARD_WIDTH],
}

impl Board {
    fn new() -> Self {
        Board {
            grid: [[None; BOARD_HEIGHT]; BOARD_WIDTH],
        }
    }

    fn is_valid(&self, piece: &Piece, px: i32, py: i32, rot: usize) -> bool {
        let shape = piece_shape(piece.piece_type, rot);
        for row in 0..4 {
            for col in 0..4 {
                if shape[row][col] {
                    let board_x = px + col as i32;
                    let board_y = py + row as i32;

                    if board_x < 0 || board_x >= BOARD_WIDTH as i32 {
                        return false;
                    }
                    if board_y >= BOARD_HEIGHT as i32 {
                        return false;
                    }
                    if board_y >= 0 && self.grid[board_x as usize][board_y as usize].is_some() {
                        return false;
                    }
                }
            }
        }
        true
    }

    fn lock_piece(&mut self, piece: &Piece) {
        let shape = piece_shape(piece.piece_type, piece.rotation);
        for row in 0..4 {
            for col in 0..4 {
                if shape[row][col] {
                    let board_x = piece.x + col as i32;
                    let board_y = piece.y + row as i32;
                    if board_y >= 0 && board_y < BOARD_HEIGHT as i32 && board_x >= 0 && board_x < BOARD_WIDTH as i32 {
                        self.grid[board_x as usize][board_y as usize] = Some(piece.piece_type);
                    }
                }
            }
        }
    }

    fn clear_lines(&mut self) -> usize {
        let mut lines_cleared = 0;
        let mut y = BOARD_HEIGHT - 1;

        while y > 0 {
            if self.grid.iter().all(|col| col[y].is_some()) {
                // Line is full, shift everything down
                for dy in (1..=y).rev() {
                    for x in 0..BOARD_WIDTH {
                        self.grid[x][dy] = self.grid[x][dy - 1];
                    }
                }
                // Clear top row
                for x in 0..BOARD_WIDTH {
                    self.grid[x][0] = None;
                }
                lines_cleared += 1;
            } else {
                y -= 1;
            }
        }
        lines_cleared
    }
}

// Game state
struct Game {
    board: Board,
    current_piece: Piece,
    next_piece: PieceType,
    score: u32,
    level: u32,
    game_over: bool,
    drop_interval: Duration,
    last_drop: Instant,
}

impl Game {
    fn new() -> Self {
        let mut rng = thread_rng();
        Game {
            board: Board::new(),
            current_piece: Piece::new([PieceType::I, PieceType::O, PieceType::T, PieceType::S, 
                                       PieceType::Z, PieceType::J, PieceType::L][rng.gen_range(0..7)]),
            next_piece: [PieceType::I, PieceType::O, PieceType::T, PieceType::S, 
                        PieceType::Z, PieceType::J, PieceType::L][rng.gen_range(0..7)],
            score: 0,
            level: 1,
            game_over: false,
            drop_interval: Duration::from_millis(1000),
            last_drop: Instant::now(),
        }
    }

    fn spawn_new_piece(&mut self) {
        let mut rng = thread_rng();
        self.current_piece = Piece::new(self.next_piece);
        self.next_piece = [PieceType::I, PieceType::O, PieceType::T, PieceType::S, 
                          PieceType::Z, PieceType::J, PieceType::L][rng.gen_range(0..7)];

        if !self.board.is_valid(&self.current_piece, self.current_piece.x, self.current_piece.y, self.current_piece.rotation) {
            self.game_over = true;
        }
    }

    fn move_piece(&mut self, dx: i32, dy: i32) -> bool {
        let new_x = self.current_piece.x + dx;
        let new_y = self.current_piece.y + dy;

        if self.board.is_valid(&self.current_piece, new_x, new_y, self.current_piece.rotation) {
            self.current_piece.x = new_x;
            self.current_piece.y = new_y;
            true
        } else {
            false
        }
    }

    fn rotate_piece(&mut self) {
        let old_rotation = self.current_piece.rotation;
        self.current_piece.rotate();

        if !self.board.is_valid(&self.current_piece, self.current_piece.x, self.current_piece.y, self.current_piece.rotation) {
            // Try wall kicks
            let kicks = [(-1, 0), (1, 0), (0, -1), (-2, 0), (2, 0)];
            let mut kicked = false;

            for (dx, dy) in kicks.iter() {
                if self.board.is_valid(&self.current_piece, self.current_piece.x + dx, self.current_piece.y + dy, self.current_piece.rotation) {
                    self.current_piece.x += dx;
                    self.current_piece.y += dy;
                    kicked = true;
                    break;
                }
            }

            if !kicked {
                self.current_piece.rotation = old_rotation;
            }
        }
    }

    fn soft_drop(&mut self) {
        if !self.move_piece(0, 1) {
            self.lock_and_spawn();
        }
    }

    fn hard_drop(&mut self) {
        while self.move_piece(0, 1) {
            self.score += 2;
        }
        self.lock_and_spawn();
    }

    fn lock_and_spawn(&mut self) {
        self.board.lock_piece(&self.current_piece);
        let lines = self.board.clear_lines();

        // Scoring: 100 * level for 1 line, 300 for 2, 500 for 3, 800 for 4
        self.score += match lines {
            1 => 100 * self.level,
            2 => 300 * self.level,
            3 => 500 * self.level,
            4 => 800 * self.level,
            _ => 0,
        };

        // Level up every 10 lines
        self.level = self.score / 1000 + 1;
        self.drop_interval = Duration::from_millis((1000 - (self.level - 1) * 100).max(100));

        self.spawn_new_piece();
    }

    fn update(&mut self) {
        if self.game_over {
            return;
        }

        if self.last_drop.elapsed() > self.drop_interval {
            self.soft_drop();
            self.last_drop = Instant::now();
        }
    }
}

// Render the game
fn render(canvas: &mut Canvas<Window>, game: &Game) {
    // Clear screen with dark background
    canvas.set_draw_color(Color::RGB(20, 20, 30));
    canvas.clear();

    // Draw board border
    canvas.set_draw_color(Color::RGB(100, 100, 100));
    canvas.draw_rect(Rect::new(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT)).unwrap();

    // Draw locked pieces
    for x in 0..BOARD_WIDTH {
        for y in 0..BOARD_HEIGHT {
            if let Some(piece_type) = game.board.grid[x][y] {
                draw_block(canvas, x as u32, y as u32, piece_color(piece_type));
            }
        }
    }

    // Draw current piece (ghost piece first)
    let mut ghost_y = game.current_piece.y;
    while game.board.is_valid(&game.current_piece, game.current_piece.x, ghost_y + 1, game.current_piece.rotation) {
        ghost_y += 1;
    }

    // Draw ghost piece (semi-transparent)
    let shape = piece_shape(game.current_piece.piece_type, game.current_piece.rotation);
    for row in 0..4 {
        for col in 0..4 {
            if shape[row][col] {
                let gx = (game.current_piece.x + col as i32) as u32;
                let gy = (ghost_y + row as i32) as u32;
                if gy < CANVAS_HEIGHT / BLOCK_SIZE {
                    canvas.set_draw_color(Color::RGBA(100, 100, 100, 100));
                    canvas.fill_rect(Rect::new(
                        gx * BLOCK_SIZE + 1,
                        gy * BLOCK_SIZE + 1,
                        BLOCK_SIZE - 2,
                        BLOCK_SIZE - 2
                    )).unwrap();
                }
            }
        }
    }

    // Draw current piece
    let shape = piece_shape(game.current_piece.piece_type, game.current_piece.rotation);
    for row in 0..4 {
        for col in 0..4 {
            if shape[row][col] {
                let px = (game.current_piece.x + col as i32) as u32;
                let py = (game.current_piece.y + row as i32) as u32;
                if py < CANVAS_HEIGHT / BLOCK_SIZE {
                    draw_block(canvas, px, py, piece_color(game.current_piece.piece_type));
                }
            }
        }
    }

    // Draw next piece preview
    canvas.set_draw_color(Color::RGB(20, 20, 30));
    canvas.fill_rect(Rect::new(CANVAS_WIDTH + 10, 10, 120, 120)).unwrap();

    canvas.set_draw_color(Color::RGB(150, 150, 150));
    canvas.draw_rect(Rect::new(CANVAS_WIDTH + 10, 10, 120, 120)).unwrap();

    let next_shape = piece_shape(game.next_piece, 0);
    for row in 0..4 {
        for col in 0..4 {
            if next_shape[row][col] {
                canvas.set_draw_color(piece_color(game.next_piece));
                canvas.fill_rect(Rect::new(
                    CANVAS_WIDTH + 20 + col as u32 * 25,
                    30 + row as u32 * 25,
                    24,
                    24
                )).unwrap();
            }
        }
    }

    // Draw score and level
    canvas.set_draw_color(Color::RGB(255, 255, 255));
    // Note: Text rendering would require TTF extension, skipping for simplicity

    canvas.present();
}

fn draw_block(canvas: &mut Canvas<Window>, x: u32, y: u32, color: Color) {
    canvas.set_draw_color(color);
    canvas.fill_rect(Rect::new(
        x * BLOCK_SIZE + 1,
        y * BLOCK_SIZE + 1,
        BLOCK_SIZE - 2,
        BLOCK_SIZE - 2
    )).unwrap();

    // Add highlight
    canvas.set_draw_color(Color::RGB(
        (color.r as u32 + 50).min(255) as u8,
        (color.g as u32 + 50).min(255) as u8,
        (color.b as u32 + 50).min(255) as u8,
    ));
    canvas.draw_rect(Rect::new(
        x * BLOCK_SIZE + 1,
        y * BLOCK_SIZE + 1,
        BLOCK_SIZE - 2,
        BLOCK_SIZE - 2
    )).unwrap();
}

fn main() {
    let sdl_context = sdl2::init().unwrap();
    let video_subsystem = sdl_context.video().unwrap();

    let window = video_subsystem
        .window("Tetris", CANVAS_WIDTH + 150, CANVAS_HEIGHT)
        .position_centered()
        .opengl()
        .build()
        .unwrap();

    let mut canvas = window.into_canvas().present_vsync().build().unwrap();
    canvas.set_draw_color(Color::RGB(0, 0, 0));
    canvas.clear();
    canvas.present();

    let mut event_pump = sdl_context.event_pump().unwrap();
    let mut game = Game::new();

    'running: loop {
        for event in event_pump.poll_iter() {
            match event {
                Event::Quit { .. } => break 'running,
                Event::KeyDown { keycode: Some(keycode), .. } => {
                    if game.game_over {
                        if keycode == Keycode::R {
                            game = Game::new();
                        }
                        continue;
                    }

                    match keycode {
                        Keycode::Left => {
                            game.move_piece(-1, 0);
                        }
                        Keycode::Right => {
                            game.move_piece(1, 0);
                        }
                        Keycode::Down => {
                            game.soft_drop();
                        }
                        Keycode::Up | Keycode::X => {
                            game.rotate_piece();
                        }
                        Keycode::Z => {
                            game.current_piece.rotate_back();
                            if !game.board.is_valid(&game.current_piece, game.current_piece.x, game.current_piece.y, game.current_piece.rotation) {
                                game.current_piece.rotate();
                            }
                        }
                        Keycode::Space => {
                            game.hard_drop();
                        }
                        Keycode::Escape => break 'running,
                        _ => {}
                    }
                }
                _ => {}
            }
        }

        game.update();
        render(&mut canvas, &game);

        std::thread::sleep(Duration::from_millis(16)); // ~60 FPS
    }
}
